using System;
using EmberBastion;
class HardModeChecks {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Main(){for(int field=0;field<3;field++){
 var b=new Battle(1,field);Check(!b.SetDifficulty(-1)&&!b.SetDifficulty(3),"invalid mode");Check(b.SetDifficulty(2)&&b.HardWaves&&b.FastWaves&&b.WaveInterval==18,"hard mode");var p=Battle.RestorePreparation(b.SavePreparation());Check(p.HardWaves&&p.FastWaves,"prep mode");Check(p.Place(0,0)&&p.Start(),"start");p.Step(1.0/60);Check(p.Enemies.Count==1&&Math.Abs(p.Enemies[0].MaxHP-Balance.Enemies[0].HP*1.8)<1e-8,"health");Check(!p.SetDifficulty(0),"locked combat");Check(p.CopyCombat().HardWaves,"checkpoint mode");Check(Battle.ImportCombat(p.ExportCombat()).HardWaves,"combat save");
 var old=new Battle(1,field);old.SetFastWaves(true);var oldData=old.SavePreparation();Check(!Battle.RestorePreparation(oldData).HardWaves,"legacy fast");oldData.hardWaves=true;oldData.fastWaves=false;bool failed=false;try{Battle.RestorePreparation(oldData);}catch(ArgumentException){failed=true;}Check(failed,"invalid flags");Check(old.SetDifficulty(2)&&old.SetFastWaves(false)&&!old.HardWaves&&!old.FastWaves,"compat reset");
 var original=new Battle(99,field);Check(original.SetDifficulty(2)&&original.GrantSupply(40)&&original.UpgradeEmber(2)&&original.Place(0,0)&&original.Start(),"combined run");for(int i=0;i<45;i++)original.Step(1.0/60);var replay=Battle.ImportCombat(original.ExportCombat());Check(replay.HardWaves&&replay.SupplyBonus==40&&replay.EmberBranch==2,"combined saved values");for(int tick=0;tick<2500&&original.Phase==Phase.Fighting;tick++){original.Step(1.0/60);replay.Step(1.0/60);if(tick%25==0){Check(original.Phase==replay.Phase&&original.Wave==replay.Wave&&original.Gold==replay.Gold&&original.Kills==replay.Kills&&original.Pending==replay.Pending&&original.Enemies.Count==replay.Enemies.Count,"replay state");for(int j=0;j<original.Enemies.Count;j++){var a=original.Enemies[j];var b2=replay.Enemies[j];Check(a.Id==b2.Id&&Math.Abs(a.HP-b2.HP)<1e-7&&Math.Abs(a.Travel-b2.Travel)<1e-7,"replay enemies");}}}
 }Console.WriteLine("PASS "+checks+" difficulty, combat, checkpoint, replay and legacy checks");}
}
